#include <vector>

// A pool of `slots` fixed slots, numbered 0 .. slots-1.
// allocate() returns a free slot, or -1 if none is free. release(s) makes slot s free again.
// The most recently released slot is the next one allocated. No call may use the heap after the constructor.
class Pool {
public:
    explicit Pool(int slots) : in_use_(0) {
        for (int s = slots - 1; s >= 0; --s) free_.push_back(s);
    }
    int allocate() {
        if (free_.empty()) return -1;
        std::vector<int> keep(free_);          // a copy of the whole list on every call
        int slot = keep.back();
        free_.pop_back();
        ++in_use_;
        return slot;
    }
    void release(int slot) { free_.push_back(slot); --in_use_; }
    int in_use() const { return in_use_; }
private:
    std::vector<int> free_;
    int in_use_;
};

