#include <vector>

// A fixed buffer of `n` ints, allocated once in the constructor and released in the destructor.
// total() adds the values up. It must not allocate.
class Buffer {
public:
    explicit Buffer(int n) : n_(n), data_(new int[n]) { for (int i = 0; i < n; ++i) data_[i] = i + 1; }
    int total() const {
        std::vector<int> copy(data_, data_ + n_);   // allocates on every call
        int s = 0;
        for (int v : copy) s += v;
        return s;
    }
private:
    int n_;
    int* data_;
};

