class Buffer {
public:
    explicit Buffer(int n) : n_(n), data_(new int[n]) { for (int i = 0; i < n; ++i) data_[i] = i + 1; }
    ~Buffer() { delete[] data_; }
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
    int total() const {
        int s = 0;
        for (int i = 0; i < n_; ++i) s += data_[i];
        return s;
    }
private:
    int n_;
    int* data_;
};
